import os,json,time,hashlib,xml.etree.ElementTree as ET
from pathlib import Path
os.environ.update(CUDA_VISIBLE_DEVICES='',OMP_NUM_THREADS='1',MKL_NUM_THREADS='1',OPENBLAS_NUM_THREADS='1',PYTHONDONTWRITEBYTECODE='1')
import numpy as np,torch,h5py
torch.set_num_threads(1)
out={}
for suite,p in PARENTS.items():
 out[suite]={}
 for t,sp in p['initial_split'].items():
  init=np.asarray(torch.load(sp['path'],map_location='cpu'));fp=next(Path('/data/mlr_ifa/datasets').rglob(Path(sp['path']).stem+'*.hdf5'));records=[]
  with h5py.File(fp,'r') as f:
   for demo in ['demo_'+str(i) for i in range(10)]:
    g=f['data'][demo];z=g['states'][0];xml=g.attrs.get('model_file','');xml=xml.decode() if isinstance(xml,bytes) else xml
    tree=ET.fromstring(xml);offset=0;free=[]
    for node in tree.find('worldbody').iter():
     if node.tag not in ['joint','freejoint']:continue
     typ='free' if node.tag=='freejoint' else node.attrib.get('type','hinge')
     if typ=='free':free.append(dict(name=node.attrib.get('name',''),qpos_offset=offset))
     offset+={'free':7,'ball':4,'slide':1,'hinge':1}[typ]
    # MuJoCo flattened state is [time,qpos,qvel,act]. No physics constructed.
    assert 1+offset<=len(z) and free
    xy=[1+x['qpos_offset']+j for x in free for j in [0,1]];xyz=[1+x['qpos_offset']+j for x in free for j in [0,1,2]]
    row=dict(demo=demo,xml_sha256=hashlib.sha256(xml.encode()).hexdigest(),free_joints=free,nq_parsed=offset)
    for label,ix in [('all_free_xy',xy),('all_free_xyz',xyz)]:
     dist=np.max(np.abs(init[:30,ix]-z[ix]),axis=1)
     row[label]=dict(nearest_index=int(dist.argmin()),nearest_linf=float(dist.min()),eval_nearest_linf=float(dist[:20].min()),training_nearest_linf=float(dist[20:].min()),matching_indices_by_absolute_tolerance={str(eps):np.where(dist<=eps)[0].tolist() for eps in [1e-8,1e-6,1e-4,1e-3]})
    records.append(row)
   # Additional online collection scenes vs formal scenes, independent of robot/time.
   ix=[1+x['qpos_offset']+j for x in free for j in [0,1]]
   pair=np.max(np.abs(init[20:30,None,ix]-init[None,:20,ix]),axis=2)
  out[suite][t]=dict(hdf5=str(fp),used_demonstrations=records,online_train_formal_free_xy_min_distance=float(pair.min()),online_train_formal_free_xy_pairs_by_tolerance={str(eps):[[int(a+20),int(b)] for a,b in np.argwhere(pair<=eps)] for eps in [1e-8,1e-6,1e-4,1e-3]},limits='Static free-joint XY/XYZ comparison ignores robot pose, velocities, articulation and post-reset physics; numerical proximity is evidence of reused layouts, not identical rollouts')
